import Foundation
import NIO
import NIOHTTP1

// FileProcessingService.swift - Kubernetes file processing microservice
// Handles async file chunk processing with callback-based completion

final class FileChunkProcessor {
    private var buffer: UnsafeMutableBufferPointer<UInt8>
    private var bytesWritten: Int = 0
    private let capacity: Int

    init(capacity: Int) {
        self.capacity = capacity
        let raw = UnsafeMutablePointer<UInt8>.allocate(capacity: capacity)
        self.buffer = UnsafeMutableBufferPointer(start: raw, count: capacity)
    }

    func appendChunk(_ data: Data) -> Bool {
        guard bytesWritten + data.count <= capacity else { return false }
        data.withUnsafeBytes { rawBuf in
            let src = rawBuf.bindMemory(to: UInt8.self)
            for i in 0..<src.count {
                buffer[bytesWritten + i] = src[i]
            }
        }
        bytesWritten += data.count
        return true
    }

    func finalize() -> Data {
        return Data(bytes: buffer.baseAddress!, count: bytesWritten)
    }

    func deallocate() {
        buffer.baseAddress?.deallocate()
    }

    deinit {
        // Note: deallocate() must be called explicitly before deinit
    }
}

final class ProcessingSession {
    let sessionId: String
    let processor: FileChunkProcessor
    private var completionCallbacks: [(Data) -> Void] = []
    private var isFinalized: Bool = false

    init(sessionId: String, maxSize: Int) {
        self.sessionId = sessionId
        self.processor = FileChunkProcessor(capacity: maxSize)
    }

    func onComplete(_ callback: @escaping (Data) -> Void) {
        completionCallbacks.append(callback)
    }

    func addChunk(_ data: Data) -> Bool {
        guard !isFinalized else { return false }
        return processor.appendChunk(data)
    }

    func finalize() {
        guard !isFinalized else { return }
        isFinalized = true
        let result = processor.finalize()
        processor.deallocate()
        for cb in completionCallbacks {
            cb(result)
        }
    }
}

final class FileProcessingService {
    private var sessions: [String: ProcessingSession] = [:]
    private let eventLoop: EventLoop
    private let maxFileSize: Int = 10 * 1024 * 1024 // 10MB

    init(eventLoop: EventLoop) {
        self.eventLoop = eventLoop
    }

    func createSession(sessionId: String) -> ProcessingSession {
        let session = ProcessingSession(sessionId: sessionId, maxSize: maxFileSize)
        sessions[sessionId] = session
        return session
    }

    func processChunk(sessionId: String, chunk: Data, isLast: Bool) -> EventLoopFuture<Data?> {
        let promise = eventLoop.makePromise(of: Data?.self)

        guard let session = sessions[sessionId] else {
            promise.fail(ServiceError.sessionNotFound)
            return promise.futureResult
        }

        guard session.addChunk(chunk) else {
            promise.fail(ServiceError.bufferOverflow)
            return promise.futureResult
        }

        if isLast {
            // Register callback that captures processor reference for post-processing
            let processor = session.processor
            session.onComplete { [weak self] finalData in
                // Schedule deferred validation on event loop
                self?.eventLoop.execute {
                    // BUG: processor.buffer was deallocated in finalize()
                    // but we access it here through the captured processor reference
                    let validationResult = self?.validateProcessedData(processor: processor)
                    if validationResult == true {
                        promise.succeed(finalData)
                    } else {
                        promise.succeed(nil)
                    }
                }
            }
            session.finalize()
            sessions.removeValue(forKey: sessionId)
        } else {
            promise.succeed(nil)
        }

        return promise.futureResult
    }

    private func validateProcessedData(processor: FileChunkProcessor) -> Bool {
        // Accesses deallocated buffer - USE AFTER FREE
        let data = processor.finalize()
        return data.count > 0
    }

    func healthCheck() -> EventLoopFuture<Bool> {
        return eventLoop.makeSucceededFuture(true)
    }
}

enum ServiceError: Error {
    case sessionNotFound
    case bufferOverflow
    case validationFailed
}

// Kubernetes readiness/liveness probe handler
final class K8sProbeHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias OutboundOut = HTTPServerResponsePart

    private let service: FileProcessingService

    init(service: FileProcessingService) {
        self.service = service
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let reqPart = unwrapInboundIn(data)
        switch reqPart {
        case .head(let head):
            if head.uri == "/healthz" || head.uri == "/readyz" {
                let response = HTTPResponseHead(version: head.version, status: .ok)
                context.write(wrapOutboundOut(.head(response)), promise: nil)
                context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
            }
        case .body, .end:
            break
        }
    }
}
